   		WLAST_b <= '0';
   		WLAST   <= '0';
   	elsif rising_edge(Clk) then
   		WLAST_b <= End_AXI_Bag_Cnt;
   		WLAST <= WLAST_b;
   	end if;
   end process;
   
   
   

   -- HDL Embedded Text Block 5 eb5
   -- eb5 5                                        
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		Rsp_Start_b <= '0';
   	elsif rising_edge(Clk) then
   		if(State_c = ST_RSP) or (State_c = ST_CRC_ERR) or (State_c = ST_UART_TIMEOUT) then
   			Rsp_Start_b <= '1';
   		else
   			Rsp_Start_b <= '0';
   		end if;
   	end if;
   end process;
   
   
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_NUM_b <= (others => '0');
   	elsif rising_edge(Clk) then
   		if(State_c = ST_CRC_CHK) then
   			REG_NUM_b <= REG_NUM_b + X"0001";
   		end if;
   	end if;
   end process;
   
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_ERR_b <= (others => '0');
   	elsif rising_edge(Clk) then
   		if(State_c = ST_CRC_ERR) then
   			REG_ERR_b <= REG_ERR_b + X"0001";
   		end if;
   	end if;
   end process;
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		Rsp_State_b <= "00";
   	elsif rising_edge(Clk) then
   		if(State_c = ST_HEAD1) then
   			Rsp_State_b <= "00";
   		elsif(State_c = ST_CRC_ERR) then
   			Rsp_State_b <= "01";
   		elsif(State_c = ST_UART_TIMEOUT) then
   			Rsp_State_b <= "10";
   		end if;
   	end if;
   end process;
   

   -- HDL Embedded Text Block 6 eb6
   -- eb6 6                                        
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_CMD_NUM_b <= (others => '0');
   	elsif rising_edge(Clk) then
   		if(Rsp_Start_p = '1') then
   			REG_CMD_NUM_b <= REG_CMD_NUM_b + X"0001";
   		end if;
   	end if;
   end process;
   

   -- HDL Embedded Text Block 7 eb7
   -- eb7 7                                        
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		REG_NUM_M1 <= (others => '0');
   		REG_RSP    <= '0';
   	elsif rising_edge(Clk) then
   		if (DRV_Valid_s = '1') and (State_c = ST_CMD_TYPE) then
   			case DRV_Data_s is
   				-- 时间码
   				when X"BB" =>
   					REG_NUM_M1 <= X"07";
   					REG_RSP    <= '0';
   				-- 反遥测
   				when X"44" =>
   					REG_NUM_M1 <= X"00";
   					REG_RSP    <= '0';
   				-- 参数帧
   				when X"22" =>
   					REG_NUM_M1 <= X"27";
   					REG_RSP    <= '1';
   				-- 拍摄使能
   				when X"AA" =>
   					REG_NUM_M1 <= X"01";
   					REG_RSP    <= '1';
   				when others =>
   					REG_NUM_M1 <= X"00";
   					REG_RSP    <= '0';
   			end case;
   		end if;
   	end if;
   end process;
   


